1	package indexroom
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"reflect"
8		"sync"
9		"testing"
10	)
11	
12	// This file is the regression net for concurrent ingestion: many Append calls
13	// racing to submit the SAME not-yet-indexed height above a valid parent.
14	//
15	// The rules under test are the existing Append rules, now exercised under real
16	// concurrency:
17	//
18	//   - Re-submitting a block identical to one already on the main chain is a
19	//     successful no-op, and equality is decided by CONTENT, so independent
20	//     copies of the same candidate all win: every call returns nil, the tip
21	//     advances exactly one height, and no occurrence (or in-block duplicate)
22	//     is gained from the repeated submissions.
23	//   - Two genuinely different candidates that both extend the same parent are
24	//     a race that exactly one content may win. Once the winning content is the
25	//     main-chain block, every call carrying identical content succeeds and
26	//     every call carrying the other content returns a NON-nil ordinary error
27	//     (never ErrInvalidArgument). The tip, the stored block, the hash->height
28	//     table, transaction queries, and the exported snapshot must ALL describe
29	//     the single winning content: no interleaved transaction list and no
30	//     overwrite following an error.
31	//
32	// Per-call outcomes are recorded and, after every call has finished, tied back
33	// to the finally stored content — merely checking the resulting block count
34	// cannot distinguish "identical replays" from "one candidate overwrote the
35	// other". Exported state (Tip, Blocks, ByHash) is read only after the
36	// WaitGroup has drained, matching the exported-fields inspection convention;
37	// queries run through the public QueryTxs/Export APIs. Everything is offline.
38	
39	// cloneCandidate returns a fully independent copy of a candidate block: a new
40	// tx backing array and a fresh timestamp pointer, so two copies share nothing
41	// mutable and "identical" can only be a judgement about content.
42	func cloneCandidate(b Block) Block {
43		cp := Block{Height: b.Height, Hash: b.Hash, Parent: b.Parent}
44		if b.Txs != nil {
45			cp.Txs = append([]string(nil), b.Txs...)
46		}
47		if b.Time != nil {
48			t := *b.Time
49			cp.Time = &t
50		}
51		return cp
52	}
53	
54	// appendResult is one call's outcome, indexed by submission position.
55	type appendResult struct {
56		block Block
57		err   error
58	}
59	
60	// raceAppendAtHeight submits every candidate concurrently at the same height
61	// (the index's tip+1, parent already on chain) and returns per-call results in
62	// submission order. It never inspects exported state; callers do that only
63	// after this returns and all goroutines have finished.
64	func raceAppendAtHeight(t *testing.T, index *Index, candidates []Block) []appendResult {
65		t.Helper()
66		start := make(chan struct{})
67		results := make([]appendResult, len(candidates))
68		var wg sync.WaitGroup
69		for i, candidate := range candidates {
70			wg.Add(1)
71			go func(i int, candidate Block) {
72				defer wg.Done()
73				<-start // release every submission together
74				results[i] = appendResult{block: candidate, err: index.Append(candidate)}
75			}(i, candidate)
76		}
77		close(start)
78		wg.Wait()
79		return results
80	}
81	
82	// raceRow ties one submitted candidate to its observed outcome.
83	type raceRow struct {
84		candidate Block
85		err       error
86	}
87	
88	// groupRaceOutcomes splits per-call results by content equality with winner
89	// and loser: every call carrying the winning content must have a nil error,
90	// every call carrying the other content a non-nil one.
91	func groupRaceOutcomes(results []appendResult, winner, loser Block) (winners, losers []raceRow) {
92		for _, r := range results {
93			switch {
94			case sameBlock(r.block, winner):
95				winners = append(winners, raceRow{r.block, r.err})
96			case sameBlock(r.block, loser):
97				losers = append(losers, raceRow{r.block, r.err})
98			default:
99				return nil, nil // a candidate that matches neither is a test-setup bug
100			}
101		}
102		return winners, losers
103	}
104	
105	// assertPerCallOutcomes ties each individual call's success/failure to the
106	// content that finally won, instead of only looking at aggregate counts. A
107	// winner-content call must have succeeded; a loser-content call must have
108	// failed with a plain error that is not ErrInvalidArgument (an ingestion
109	// rejection stays an ordinary error, not a query-argument error).
110	func assertPerCallOutcomes(t *testing.T, results []appendResult, winner, loser Block) {
111		t.Helper()
112		winners, losers := groupRaceOutcomes(results, winner, loser)
113		if winners == nil || losers == nil || len(winners)+len(losers) != len(results) {
114			t.Fatalf("test setup: a submitted candidate matched neither variant:\n%+v", results)
115		}
116		if len(winners) == 0 {
117			t.Fatal("no call carried the winning content")
118		}
119		if len(losers) == 0 {
120			t.Fatal("no call carried the losing content")
121		}
122		for i, row := range winners {
123			if row.err != nil {
124				t.Fatalf("winner-content call #%d (%+v) failed: %v", i, row.candidate, row.err)
125			}
126		}
127		for i, row := range losers {
128			if row.err == nil {
129				t.Fatalf("loser-content call #%d (%+v) succeeded; different content at one height must be rejected",
130					i, row.candidate)
131			}
132			if errors.Is(row.err, ErrInvalidArgument) {
133				t.Fatalf("loser-content call #%d returned ErrInvalidArgument; ingestion rejections stay ordinary errors: %v",
134					i, row.err)
135			}
136		}
137	}
138	
139	// assertStoredWinner verifies the complete post-race chain describes exactly
140	// the winning content, read only after all calls finished: tip advanced once,
141	// the stored block equals the winner (including nil-vs-empty txs and
142	// nil-vs-zero time), the hash table agrees, and nothing above the new height
143	// exists.
144	func assertStoredWinner(t *testing.T, index *Index, parentTip int64, winner Block) {
145		t.Helper()
146		height := winner.Height
147		if index.Tip != height {
148			t.Fatalf("tip=%d, want exactly the one new height %d", index.Tip, height)
149		}
150		stored, ok := index.Blocks[height]
151		if !ok {
152			t.Fatalf("height %d missing after the race", height)
153		}
154		if !sameBlock(stored, winner) {
155			t.Fatalf("stored block at %d = %+v, want winning content %+v", height, stored, winner)
156		}
157		if parentTip > 0 && stored.Parent != index.Blocks[parentTip].Hash {
158			t.Fatalf("winner parent %q does not chain onto retained parent block %q",
159				stored.Parent, index.Blocks[parentTip].Hash)
160		}
161		if got := index.ByHash[stored.Hash]; got != height {
162			t.Fatalf("by-hash maps winning hash %q to %d, want %d", stored.Hash, got, height)
163		}
164		if _, present := index.Blocks[height+1]; present {
165			t.Fatal("a block exists above the contended height")
166		}
167		if int64(len(index.Blocks)) != height {
168			t.Fatalf("block count=%d, want %d (tip advanced exactly once)", len(index.Blocks), height)
169		}
170	}
171	
172	// assertWinnerQuery verifies QueryTxs reflects only the winning block's own
173	// occurrences: each winner tx appears at its original in-block position, the
174	// TotalMatches/MatchedBlocks counts ignore how many times the block was
175	// submitted, and no tx carried only by the loser leaks through. Hits are read
176	// via the public API after ingestion finished.
177	func assertWinnerQuery(t *testing.T, index *Index, winner, loser Block) {
178		t.Helper()
179		height := winner.Height
180		page, err := index.QueryTxs(TxQuery{From: height, To: height, PageSize: MaxPageSize})
181		if err != nil {
182			t.Fatalf("query at contended height failed: %v", err)
183		}
184		var want []TxHit = []TxHit{}
185		for position, tx := range winner.Txs {
186			want = append(want, TxHit{Height: height, BlockHash: winner.Hash, TxID: tx, Position: position})
187		}
188		if !reflect.DeepEqual(page.Hits, want) {
189			t.Fatalf("hits at %d =\n%+v\nwant winner occurrences (original order/duplicates/positions):\n%+v",
190				height, page.Hits, want)
191		}
192		// A block with no transactions holds no matches and is not a matched block.
193		wantMatchedBlocks := int64(0)
194		if len(winner.Txs) > 0 {
195			wantMatchedBlocks = 1
196		}
197		if page.TotalMatches != int64(len(winner.Txs)) || page.MatchedBlocks != wantMatchedBlocks || page.ToHeight != height {
198			t.Fatalf("page stats=%d/%d/%d, want %d/%d/%d",
199				page.TotalMatches, page.MatchedBlocks, page.ToHeight,
200				len(winner.Txs), wantMatchedBlocks, height)
201		}
202		if page.NextCursor != "" {
203			t.Fatalf("single-height page must end without a cursor, got %q", page.NextCursor)
204		}
205		// Nothing the losing block carried may show up at the height.
206		loserOnly := map[string]bool{}
207		for _, tx := range loser.Txs {
208			loserOnly[tx] = true
209		}
210		for _, tx := range winner.Txs {
211			delete(loserOnly, tx)
212		}
213		for tx := range loserOnly {
214			page, err := index.QueryTxs(TxQuery{From: height, To: height, TxIDs: []string{tx}})
215			if err != nil {
216				t.Fatalf("query for loser-only tx %q failed: %v", tx, err)
217			}
218			if len(page.Hits) != 0 || page.TotalMatches != 0 {
219				t.Fatalf("loser-only tx %q leaked into the winning height: %+v", tx, page)
220			}
221		}
222		// Querying the whole chain still sees exactly one complete chain whose
223		// occurrence count is the pre-race chain plus the winner's own txs.
224		all, err := index.QueryTxs(TxQuery{PageSize: MaxPageSize})
225		if err != nil {
226			t.Fatalf("whole-chain query failed: %v", err)
227		}
228		if all.ToHeight != height {
229			t.Fatalf("whole-chain ToHeight=%d, want %d", all.ToHeight, height)
230		}
231		parentCount := int64(0)
232		for h := int64(1); h < height; h++ {
233			parentCount += int64(len(index.Blocks[h].Txs))
234		}
235		if all.TotalMatches != parentCount+int64(len(winner.Txs)) {
236			t.Fatalf("whole-chain TotalMatches=%d, want %d (parent chain %d + winner txs %d)",
237				all.TotalMatches, parentCount+int64(len(winner.Txs)), parentCount, len(winner.Txs))
238		}
239	}
