241	// exportBytes returns the canonical snapshot for cross-checking that the
242	// persisted view agrees with the winning chain as built independently.
243	func exportBytes(t *testing.T, index *Index) []byte {
244		t.Helper()
245		var buf bytes.Buffer
246		if err := index.Export(&buf); err != nil {
247			t.Fatalf("export failed: %v", err)
248		}
249		return buf.Bytes()
250	}
251	
252	// assertWinnerSnapshot builds an independent oracle index by replaying the
253	// final chain serially (pre-race parent blocks plus the winning block) and
254	// requires its canonical export to be byte-identical to the raced index
255	// export. The oracle never shares an Append call with the index under test, so
256	// a shared ingestion bug cannot make the expectation match itself.
257	func assertWinnerSnapshot(t *testing.T, index *Index, parents []Block, winner Block) {
258		t.Helper()
259		oracle := New()
260		for _, b := range parents {
261			if err := oracle.Append(b); err != nil {
262				t.Fatalf("oracle setup append at %d: %v", b.Height, err)
263			}
264		}
265		if err := oracle.Append(cloneCandidate(winner)); err != nil {
266			t.Fatalf("oracle append of winner at %d failed: %v", winner.Height, err)
267		}
268		if got, want := exportBytes(t, index), exportBytes(t, oracle); !bytes.Equal(got, want) {
269			t.Fatalf("raced export:\n%s\noracle export (parents + winner):\n%s", got, want)
270		}
271		// Round-tripping through a snapshot must preserve the same content as
272		// well, covering the snapshot behaviour alongside ingestion.
273		restored := New()
274		if err := restored.Restore(bytes.NewReader(exportBytes(t, index))); err != nil {
275			t.Fatalf("restore of raced export failed: %v", err)
276		}
277		if got, want := exportBytes(t, restored), exportBytes(t, oracle); !bytes.Equal(got, want) {
278			t.Fatalf("restored export diverges from oracle:\n%s\nwant:\n%s", got, want)
279		}
280	}
