337	// appendRaceFixtures covers the content distinctions called out by the
338	// ingestion rules: different transaction sets, order-only and timestamp-only
339	// differences under identical hash/parent, nil-vs-zero timestamp, and the
340	// nil-vs-empty tx list equivalence (which is therefore NOT a conflict and gets
341	// its own identical-content test).
342	func appendRaceFixtures() []raceFixture {
343		baseParent := []Block{{Height: 1, Hash: "p1", Parent: "genesis", Txs: []string{"g1"}}}
344		parentWithTime := []Block{{Height: 1, Hash: "p1", Parent: "genesis", Txs: []string{"g1"}, Time: intptr(10)}}
345		zero := int64(0)
346		seven := int64(7)
347		return []raceFixture{
348			{
349				name:    "different tx sets",
350				parents: baseParent,
351				winner:  Block{Height: 2, Hash: "c2", Parent: "p1", Txs: []string{"a", "b", "a"}},
352				loser:   Block{Height: 2, Hash: "d2", Parent: "p1", Txs: []string{"a", "c"}},
353			},
354			{
355				name:    "same hash and parent, tx order differs",
356				parents: baseParent,
357				winner:  Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a", "b", "a"}},
358				loser:   Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a", "a", "b"}},
359			},
360			{
361				name:    "same hash parent and txs, timestamp provided vs missing",
362				parents: parentWithTime,
363				winner:  Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a"}, Time: &seven},
364				loser:   Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a"}},
365			},
366			{
367				name:    "missing timestamp vs real zero are two contents",
368				parents: baseParent,
369				winner:  Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a"}},
370				loser:   Block{Height: 2, Hash: "same", Parent: "p1", Txs: []string{"a"}, Time: &zero},
371			},
372			{
373				name:    "different tx sets with same timestamp",
374				parents: baseParent,
375				winner:  Block{Height: 2, Hash: "c2", Parent: "p1", Txs: []string{"x"}, Time: &seven},
376				loser:   Block{Height: 2, Hash: "d2", Parent: "p1", Txs: []string{"y"}, Time: &seven},
377			},
378		}
379	}
