506	// TestConcurrentAppendConflictingCandidatesOneContentWins: for every content
507	// distinction in the fixtures, two candidate contents race with multiple
508	// independent copies each. Either content may be accepted first — the test
509	// never designates a winner — but once one is the main-chain block, per-call
510	// success/failure must line up with the finally stored content, and the whole
511	// observable state must describe that one content.
512	func TestConcurrentAppendConflictingCandidatesOneContentWins(t *testing.T) {
513		for _, fixture := range appendRaceFixtures() {
514			t.Run(fixture.name, func(t *testing.T) {
515				validateRaceFixture(t, fixture)
516	
517				// Run several rounds; because either content may win and the test
518				// derives expectations from the actual winner, every round is a
519				// valid outcome and the assertions are independent of scheduling.
520				const rounds = 8
521				const copiesEach = 8
522				for round := 0; round < rounds; round++ {
523					t.Run(fmt.Sprintf("round%d", round), func(t *testing.T) {
524						index := New()
525						for _, b := range fixture.parents {
526							if err := index.Append(b); err != nil {
527								t.Fatalf("setup append at %d: %v", b.Height, err)
528							}
529						}
530						candidates := make([]Block, 0, 2*copiesEach)
531						for i := 0; i < copiesEach; i++ {
532							candidates = append(candidates, cloneCandidate(fixture.winner))
533							candidates = append(candidates, cloneCandidate(fixture.loser))
534						}
535						results := raceAppendAtHeight(t, index, candidates)
536	
537						// Determine the winner from the finally stored content,
538						// not from whichever call happened to run first. State is
539						// inspected only after every call has returned.
540						height := fixture.winner.Height
541						stored := index.Blocks[height]
542						var winner, loser Block
543						switch {
544						case sameBlock(stored, fixture.winner):
545							winner, loser = fixture.winner, fixture.loser
546						case sameBlock(stored, fixture.loser):
547							winner, loser = fixture.loser, fixture.winner
548						default:
549							t.Fatalf("stored block at %d matches neither candidate: %+v", height, stored)
550						}
551	
552						assertPerCallOutcomes(t, results, winner, loser)
553						assertStoredWinner(t, index, int64(len(fixture.parents)), winner)
554						assertWinnerQuery(t, index, winner, loser)
555						assertWinnerSnapshot(t, index, fixture.parents, winner)
556					})
557				}
558			})
559		}
560	}
