562	// TestConcurrentAppendSameHeightRaceLeavesNoOrphanHashes: the loser's hash
563	// must never enter the hash index, and the losing txs must not be queryable —
564	// an error return can never have partially installed its block.
565	func TestConcurrentAppendSameHeightRaceLeavesNoOrphanHashes(t *testing.T) {
566		fixture := raceFixture{
567			name:    "orphan check",
568			parents: []Block{{Height: 1, Hash: "p1", Parent: "genesis", Txs: []string{"g1"}}},
569			winner:  Block{Height: 2, Hash: "win2", Parent: "p1", Txs: []string{"keep"}},
570			loser:   Block{Height: 2, Hash: "lose2", Parent: "p1", Txs: []string{"drop", "drop"}},
571		}
572		validateRaceFixture(t, fixture)
573	
574		for round := 0; round < 6; round++ {
575			t.Run(fmt.Sprintf("round%d", round), func(t *testing.T) {
576				index := New()
577				if err := index.Append(fixture.parents[0]); err != nil {
578					t.Fatal(err)
579				}
580				candidates := []Block{
581					cloneCandidate(fixture.winner), cloneCandidate(fixture.winner),
582					cloneCandidate(fixture.loser), cloneCandidate(fixture.loser),
583				}
584				results := raceAppendAtHeight(t, index, candidates)
585	
586				var winner, loser Block
587				if index.ByHash["win2"] == 2 {
588					winner, loser = fixture.winner, fixture.loser
589				} else {
590					winner, loser = fixture.loser, fixture.winner
591				}
592				assertPerCallOutcomes(t, results, winner, loser)
593	
594				losingHash := loser.Hash
595				if _, present := index.ByHash[losingHash]; present {
596					t.Fatalf("losing hash %q entered the hash index", losingHash)
597				}
598				for _, tx := range loser.Txs {
599					page, err := index.QueryTxs(TxQuery{From: 2, To: 2, TxIDs: []string{tx}})
600					if err != nil {
601						t.Fatalf("query losing tx %q failed: %v", tx, err)
602					}
603					if len(page.Hits) != 0 {
604						t.Fatalf("losing tx %q was indexed despite rejection: %+v", tx, page.Hits)
605					}
606				}
607				// Exactly the parent hashes plus the single winning hash exist.
608				wantHashes := map[string]int64{"p1": 1, winner.Hash: 2}
609				if !reflect.DeepEqual(map[string]int64(index.ByHash), wantHashes) {
610					t.Fatalf("ByHash=%v, want %v", index.ByHash, wantHashes)
611				}
612			})
613		}
614	}
