616	// TestConcurrentAppendAtHeightOneCoversFirstBlockRule: the same identical-vs-
617	// conflicting guarantee applies when the contended height is 1 on an empty
618	// index (the parent is just the chain-start identifier and need not exist).
619	func TestConcurrentAppendAtHeightOneCoversFirstBlockRule(t *testing.T) {
620		t.Run("identical first blocks all succeed", func(t *testing.T) {
621			block := Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"a", "a"}}
622			candidates := make([]Block, 12)
623			for i := range candidates {
624				candidates[i] = cloneCandidate(block)
625			}
626			index := New()
627			results := raceAppendAtHeight(t, index, candidates)
628			for i, r := range results {
629				if r.err != nil {
630					t.Fatalf("identical height-1 call #%d failed: %v", i, r.err)
631				}
632			}
633			assertStoredWinner(t, index, 0, block)
634			// Parent tip 0 has no block; check the snapshot against the winner
635			// directly rather than via the parent-chain oracle helper.
636			oracle := New()
637			if err := oracle.Append(cloneCandidate(block)); err != nil {
638				t.Fatal(err)
639			}
640			if !bytes.Equal(exportBytes(t, index), exportBytes(t, oracle)) {
641				t.Fatal("height-1 raced export differs from a serial one")
642			}
643		})
644	
645		t.Run("conflicting first blocks keep one content", func(t *testing.T) {
646			a := Block{Height: 1, Hash: "same", Parent: "genesis", Txs: []string{"a"}}
647			b := Block{Height: 1, Hash: "same", Parent: "genesis", Txs: []string{"b"}}
648			for round := 0; round < 6; round++ {
649				t.Run(fmt.Sprintf("round%d", round), func(t *testing.T) {
650					index := New()
651					candidates := []Block{
652						cloneCandidate(a), cloneCandidate(a), cloneCandidate(a),
653						cloneCandidate(b), cloneCandidate(b), cloneCandidate(b),
654					}
655					results := raceAppendAtHeight(t, index, candidates)
656					stored := index.Blocks[1]
657					winner, loser := a, b
658					if sameBlock(stored, b) {
659						winner, loser = b, a
660					} else if !sameBlock(stored, a) {
661						t.Fatalf("stored height-1 block matches neither candidate: %+v", stored)
662					}
663					assertPerCallOutcomes(t, results, winner, loser)
664					if index.Tip != 1 || index.ByHash[winner.Hash] != 1 {
665						t.Fatalf("unexpected state: tip=%d byHash=%v", index.Tip, index.ByHash)
666					}
667					page, err := index.QueryTxs(TxQuery{From: 1, To: 1, TxIDs: []string{loser.Txs[0]}})
668					if err != nil {
669						t.Fatal(err)
670					}
671					if len(page.Hits) != 0 {
672						t.Fatalf("losing height-1 tx %q was indexed", loser.Txs[0])
673					}
674				})
675			}
676		})
677	}
