158	// The counting and ordering semantics the regression rests on, asserted for
159	// each chain and cross-checked against the live index before and after the
160	// reorg.
161	func TestReorgQueryFixtureSemanticsOnBothChains(t *testing.T) {
162		oldChain := queryOldChainBlocks()
163		newChain := queryNewChainBlocks()
164	
165		// Setup invariant: suffix identifier sets must be disjoint and every
166		// suffix hash must differ, otherwise a mixed page could be
167		// indistinguishable by content.
168		oldIDs := map[string]struct{}{}
169		for _, b := range oldChain[2:] {
170			for _, tx := range b.Txs {
171				oldIDs[tx] = struct{}{}
172			}
173		}
174		for _, b := range newChain[2:] {
175			for _, tx := range b.Txs {
176				if _, conflict := oldIDs[tx]; conflict {
177					t.Fatalf("setup invariant broken: new-branch tx %q also exists on the old suffix", tx)
178				}
179			}
180		}
181	
182		oldHits := referenceTxHits(oldChain)
183		wantOld := []TxHit{
184			{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
185			{Height: 1, BlockHash: "h1", TxID: "x", Position: 1},
186			{Height: 4, BlockHash: "h4", TxID: "d", Position: 0},
187			{Height: 4, BlockHash: "h4", TxID: "d", Position: 1},
188			{Height: 5, BlockHash: "h5", TxID: "g", Position: 2},
189		}
190		for _, want := range wantOld {
191			if !containsHit(oldHits, want) {
192				t.Fatalf("old chain misses literal occurrence %+v in %v", want, oldHits)
193			}
194		}
195		if len(oldHits) != 10 || referenceMatchedBlocks(oldChain) != 5 {
196			t.Fatalf("old chain: hits=%d blocks=%d, want 10/5", len(oldHits), referenceMatchedBlocks(oldChain))
197		}
198		newHits := referenceTxHits(newChain)
199		if len(newHits) != 8 || referenceMatchedBlocks(newChain) != 4 {
200			t.Fatalf("new chain: hits=%d blocks=%d, want 8/4", len(newHits), referenceMatchedBlocks(newChain))
201		}
202		// h4's two d's are one block; j4's two r's are one block; removed
203		// height 5 is simply absent.
204		for _, gone := range []TxHit{
205			{Height: 5, BlockHash: "h5", TxID: "e", Position: 0},
206			{Height: 4, BlockHash: "h4", TxID: "d", Position: 0},
207		} {
208			if containsHit(newHits, gone) {
209				t.Fatalf("new chain must not carry %+v", gone)
210			}
211		}
212		if !containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "r", Position: 0}) ||
213			!containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "r", Position: 2}) {
214			t.Fatalf("new chain must keep both r occurrences: %v", newHits)
215		}
216		// Every occurrence list is ordered by height then position.
217		requireOrdered(t, oldHits)
218		requireOrdered(t, newHits)
219	
220		// The oracle must match the live index on both complete chain states.
221		index := buildQueryOldChain(t)
222		live, err := index.QueryTxs(TxQuery{})
223		if err != nil {
224			t.Fatal(err)
225		}
226		if !reflect.DeepEqual(live.Hits, oldHits) || live.TotalMatches != 10 || live.MatchedBlocks != 5 || live.ToHeight != 5 {
227			t.Fatalf("live old-chain query=%+v, want 10/5/tip5", live)
228		}
229		dropped, err := index.Reorg(queryNewShortBranch())
230		if err != nil {
231			t.Fatalf("shortening reorg refused: %v", err)
232		}
233		if want := []int64{3, 4, 5}; !reflect.DeepEqual(dropped, want) {
234			t.Fatalf("dropped=%v, want %v", dropped, want)
235		}
236		if index.Tip != 4 {
237			t.Fatalf("tip=%d, want shortened tip 4", index.Tip)
238		}
239		if _, ok := index.Blocks[5]; ok {
240			t.Fatal("height 5 still present after shortening reorg")
241		}
242		if _, ok := index.ByHash["h5"]; ok {
243			t.Fatal("removed hash h5 still indexed")
244		}
245		live, err = index.QueryTxs(TxQuery{})
246		if err != nil {
247			t.Fatal(err)
248		}
249		if !reflect.DeepEqual(live.Hits, newHits) || live.TotalMatches != 8 || live.MatchedBlocks != 4 || live.ToHeight != 4 {
250			t.Fatalf("live new-chain query=%+v, want 8/4/tip4", live)
251		}
252	}
